//! Offline replay harness (P3.5).
//!
//! [`SemioticPipeline`] wires the three semiogenesis layers —
//! `IconRing` → `IndexCorrelator` → `SymbolRecogniser` — into a single
//! call-through surface. Feed it timestamped `(channel, sample)` pairs
//! and it emits every Icon, Index, and Symbol event generated by that
//! sample stream, in causal order, via one callback.
//!
//! This module is `no_std`, heap-free, and `unsafe`-free. The same
//! pipeline drives on-device runs (live percepts) and host-side replay
//! (sensor logs) — the only difference is where the `(ts, channel,
//! sample)` tuples come from.
//!
//! ## Event ordering
//!
//! One `observe` call produces, in order:
//! 1. An optional `Icon` event (if the icon layer fired).
//! 2. Zero or more `Index` events (one per other occupied channel whose
//!    most-recent icon lies inside `DEFAULT_WINDOW_MS`).
//! 3. Zero or one `Symbol` event per emitted Index event (if the
//!    recurrence threshold was reached).
//!
//! Symbol events are interleaved with the Index event that triggered
//! them, not deferred to the end of the call.

use crate::icon::{IconEvent, IconRing};
use crate::index::IndexCorrelator;
use crate::symbol::{SymbolEvent, SymbolRecogniser};
use crate::{TimestampUs, Q15};

/// Default icon-layer ring width. Matches ADR-0013's `WINDOW = 64`.
pub const DEFAULT_ICON_WINDOW: usize = 64;

/// Default icon-layer histogram resolution. Matches ADR-0013's `BINS = 8`.
pub const DEFAULT_ICON_BINS: usize = 8;

/// One pipeline emission. Tagged across the three semiotic layers so a
/// single callback can consume all events without branching on shape
/// at the call site.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub enum PipelineEvent {
    /// An [`IconEvent`] from the icon layer.
    Icon(IconEvent),
    /// An [`crate::index::IndexEvent`] from the index layer.
    Index(crate::index::IndexEvent),
    /// A [`SymbolEvent`] from the symbol layer.
    Symbol(SymbolEvent),
}

/// Pipeline-level error. Mirrors the component errors so callers don't
/// need to pattern-match against three enums.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub enum PipelineError {
    /// The icon-layer ring table is full; a new channel can't be
    /// registered.
    IconChannelFull,
    /// The index- or symbol-layer slot table is full.
    CorrelatorChannelFull,
}

/// End-to-end semiogenesis pipeline over `C` channels.
///
/// `W` is the icon-layer rolling window (samples); `B` is the icon-
/// layer entropy-histogram bin count. Power-of-two `B` is strongly
/// preferred — see `docs/decisions.md` § ADR-0013.
///
/// State is `O(C × (W + B))` bytes for the icon rings plus the
/// IndexCorrelator and SymbolRecogniser; all stack-allocated.
pub struct SemioticPipeline<const C: usize, const W: usize, const B: usize> {
    /// Channel id at each slot; only `0..occupied` is valid.
    channels: [u16; C],
    /// Number of distinct channels registered so far.
    occupied: usize,
    /// Per-channel icon rings. `rings[i].channel() == channels[i]` for
    /// `i < occupied`; for `i >= occupied` the ring is in its new-state
    /// placeholder (channel=0) and never observed.
    rings: [IconRing<W, B>; C],
    /// Downstream correlator.
    index: IndexCorrelator<C>,
    /// Downstream recogniser.
    symbol: SymbolRecogniser<C>,
}

impl<const C: usize, const W: usize, const B: usize> SemioticPipeline<C, W, B> {
    /// Construct a pipeline with the ADR-pinned default parameters on
    /// every layer.
    pub fn new() -> Self {
        Self {
            channels: [0u16; C],
            occupied: 0,
            rings: core::array::from_fn(|_| IconRing::<W, B>::new(0)),
            index: IndexCorrelator::new(),
            symbol: SymbolRecogniser::new(),
        }
    }

    /// Number of distinct channels registered so far.
    #[inline]
    pub fn occupied(&self) -> usize {
        self.occupied
    }

    /// Compile-time channel capacity.
    #[inline]
    pub const fn capacity(&self) -> usize {
        C
    }

    /// Feed one sample through the pipeline, firing `on_event` for every
    /// emitted [`PipelineEvent`].
    ///
    /// - Registers `channel` on first sight (slot allocation).
    /// - Delegates ring aggregation to the per-channel [`IconRing`].
    /// - On icon emission, feeds the event to the [`IndexCorrelator`]
    ///   and then each emitted index event to the [`SymbolRecogniser`].
    pub fn observe<F>(
        &mut self,
        channel: u16,
        sample: Q15,
        now_us: TimestampUs,
        mut on_event: F,
    ) -> Result<(), PipelineError>
    where
        F: FnMut(PipelineEvent),
    {
        let slot = match self.find_slot(channel) {
            Some(i) => i,
            None => {
                if self.occupied >= C {
                    return Err(PipelineError::IconChannelFull);
                }
                let i = self.occupied;
                self.channels[i] = channel;
                self.rings[i] = IconRing::<W, B>::new(channel);
                self.occupied += 1;
                i
            }
        };

        let Some(icon) = self.rings[slot].observe(sample, now_us) else {
            return Ok(());
        };
        on_event(PipelineEvent::Icon(icon));

        // Buffer index emissions before draining them into the symbol
        // recogniser so we don't double-borrow `on_event`.
        let mut index_buf: heapless::Vec<crate::index::IndexEvent, C> = heapless::Vec::new();
        self.index
            .observe(&icon, |e| {
                // Pipeline capacity bounds this — push cannot overflow.
                let _ = index_buf.push(e);
            })
            .map_err(|_| PipelineError::CorrelatorChannelFull)?;

        for idx in &index_buf {
            on_event(PipelineEvent::Index(*idx));
            self.symbol
                .observe(idx, |s| on_event(PipelineEvent::Symbol(s)))
                .map_err(|_| PipelineError::CorrelatorChannelFull)?;
        }
        Ok(())
    }

    #[inline]
    fn find_slot(&self, channel: u16) -> Option<usize> {
        let mut i = 0;
        while i < self.occupied {
            if self.channels[i] == channel {
                return Some(i);
            }
            i += 1;
        }
        None
    }
}

impl<const C: usize, const W: usize, const B: usize> Default for SemioticPipeline<C, W, B> {
    fn default() -> Self {
        Self::new()
    }
}

// ── Log source + slice replay ──────────────────────────────────────────────

/// One entry in a sensor log. All logs reduce to a time-ordered stream
/// of these tuples regardless of on-disk format.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct LogEntry {
    /// Monotone timestamp in microseconds.
    pub ts_us: TimestampUs,
    /// Channel identifier. Interpretation is vocabulary-specific.
    pub channel: u16,
    /// Sample value.
    pub sample: Q15,
}

/// Drive a slice of [`LogEntry`]s through the pipeline. The callback is
/// invoked once per emitted [`PipelineEvent`] across all three layers.
///
/// Returns the count of observe calls issued; useful for quick replay
/// statistics without instrumenting the callback.
pub fn replay_slice<F, const C: usize, const W: usize, const B: usize>(
    pipeline: &mut SemioticPipeline<C, W, B>,
    entries: &[LogEntry],
    mut on_event: F,
) -> Result<usize, PipelineError>
where
    F: FnMut(PipelineEvent),
{
    for e in entries {
        pipeline.observe(e.channel, e.sample, e.ts_us, &mut on_event)?;
    }
    Ok(entries.len())
}

// ── Tests ──────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    const W: usize = DEFAULT_ICON_WINDOW;
    const B: usize = DEFAULT_ICON_BINS;

    fn step_sample(i: usize) -> Q15 {
        // Alternating pattern is enough to keep entropy high across a
        // 64-sample ring; amplitude is half-scale so saturating-mul
        // headroom isn't an issue in tests.
        if i.is_multiple_of(2) {
            Q15::from_raw(18_000)
        } else {
            Q15::from_raw(-18_000)
        }
    }

    #[test]
    fn new_pipeline_is_empty() {
        let p: SemioticPipeline<4, W, B> = SemioticPipeline::new();
        assert_eq!(p.occupied(), 0);
        assert_eq!(p.capacity(), 4);
    }

    #[test]
    fn observe_registers_new_channel() {
        let mut p: SemioticPipeline<4, W, B> = SemioticPipeline::new();
        p.observe(7, Q15::ZERO, 1_000, |_| {}).unwrap();
        assert_eq!(p.occupied(), 1);
    }

    #[test]
    fn channel_full_returns_error() {
        let mut p: SemioticPipeline<2, W, B> = SemioticPipeline::new();
        p.observe(1, Q15::ZERO, 100, |_| {}).unwrap();
        p.observe(2, Q15::ZERO, 200, |_| {}).unwrap();
        let err = p.observe(3, Q15::ZERO, 300, |_| {});
        assert_eq!(err, Err(PipelineError::IconChannelFull));
    }

    #[test]
    fn replay_slice_drives_pipeline() {
        let mut p: SemioticPipeline<4, W, B> = SemioticPipeline::new();
        let mut events = 0usize;
        // 128 samples on one channel — well past the ring's warm-up.
        let mut log: heapless::Vec<LogEntry, 256> = heapless::Vec::new();
        for i in 0..128 {
            log.push(LogEntry {
                ts_us: 1_000 + i as u64 * 10_000,
                channel: 1,
                sample: step_sample(i),
            })
            .unwrap();
        }
        let n = replay_slice(&mut p, &log, |_| events += 1).unwrap();
        assert_eq!(n, 128);
        // Not asserting exact emission count — the icon layer's
        // baseline-vs-delta trigger makes that brittle. Smoke test
        // only: call through ran without errors.
        let _ = events;
    }

    #[test]
    fn two_channels_interleave_produces_index_events_on_cofire() {
        // Craft a stream that pumps both channels through their ring
        // warmup with a strong alternating pattern, so icons fire on
        // both and the correlator sees them within the 500 ms window.
        let mut p: SemioticPipeline<4, W, B> = SemioticPipeline::new();
        let mut log: heapless::Vec<LogEntry, 1024> = heapless::Vec::new();
        for i in 0..(W * 3) {
            log.push(LogEntry {
                ts_us: 1_000 + i as u64 * 10_000,
                channel: 1,
                sample: step_sample(i),
            })
            .unwrap();
            log.push(LogEntry {
                ts_us: 1_500 + i as u64 * 10_000,
                channel: 2,
                sample: step_sample(i + 3),
            })
            .unwrap();
        }
        let mut icons = 0usize;
        let mut indices = 0usize;
        let mut symbols = 0usize;
        replay_slice(&mut p, &log, |e| match e {
            PipelineEvent::Icon(_) => icons += 1,
            PipelineEvent::Index(_) => indices += 1,
            PipelineEvent::Symbol(_) => symbols += 1,
        })
        .unwrap();
        // Smoke: both channels registered.
        assert_eq!(p.occupied(), 2);
        // Useful signal: icons fired at all (ring + trigger work).
        // Index/symbol counts depend on exact timing; we merely assert
        // nothing blew up and the pipeline state advanced.
        let _ = (icons, indices, symbols);
    }

    #[test]
    fn pipeline_event_variants_are_distinct() {
        use crate::index::IndexEvent;
        let icon = IconEvent {
            channel: 1,
            formed_at: 100,
            entropy: Q15::ZERO,
            magnitude: Q15::from_raw(10_000),
        };
        let idx = IndexEvent {
            channels: [1, 2],
            delta_us: 500,
            formed_at: 100,
            coherence: Q15::from_raw(10_000),
        };
        let sym = SymbolEvent {
            channels: [1, 2],
            formed_at: 100,
            coherence: Q15::from_raw(10_000),
        };
        let a = PipelineEvent::Icon(icon);
        let b = PipelineEvent::Index(idx);
        let c = PipelineEvent::Symbol(sym);
        assert_ne!(a, b);
        assert_ne!(b, c);
        assert_ne!(a, c);
    }
}
